const DEFAULT_PREFS: Prefs = { language: 'ru', pollMs: 2000, theme: 'dark' };

function readAuth(): GitHubAuth | null {
  try {
    const parsed = JSON.parse(localStorage.getItem(AUTH_KEY) || 'null') as Partial<GitHubAuth> | null;
    if (!parsed?.username?.trim()) return null;
    return { username: parsed.username.trim(), token: parsed.token?.trim() || '' };
  } catch { return null; }
}
function writeAuth(auth: GitHubAuth) { localStorage.setItem(AUTH_KEY, JSON.stringify(auth)); window.dispatchEvent(new Event('devdock:auth')); }
function clearAuth() { localStorage.removeItem(AUTH_KEY); window.dispatchEvent(new Event('devdock:auth')); }
function readPrefs(): Prefs { try { const p = JSON.parse(localStorage.getItem(PREFS_KEY) || '{}') as Partial<Prefs>; const pollMs = p.pollMs === 1000 || p.pollMs === 2000 || p.pollMs === 3000 ? p.pollMs : DEFAULT_PREFS.pollMs; return { ...DEFAULT_PREFS, ...p, pollMs }; } catch { return DEFAULT_PREFS; } }
function writePrefs(prefs: Prefs) { localStorage.setItem(PREFS_KEY, JSON.stringify(prefs)); window.dispatchEvent(new Event('devdock:prefs')); }

function relative(iso: string) { const d = Math.max(0, Date.now() - new Date(iso).getTime()); const m = 60_000; const h = 60*m; const day = 24*h; if (d < h) return `${Math.max(1, Math.floor(d/m))}m`; if (d < day) return `${Math.floor(d/h)}h`; if (d < 7*day) return `${Math.floor(d/day)}d`; return new Date(iso).toLocaleDateString(undefined,{month:'short',day:'numeric'}); }
function eventText(e: GitHubEvent, lang: 'ru'|'en') { const repo = e.repo.name.split('/').pop() || e.repo.name; const dict = lang === 'ru' ? { PushEvent: `Запушены коммиты в`, PullRequestEvent: `Обновлён pull request в`, IssuesEvent: `Изменён issue в`, WatchEvent: `Добавлена звезда`, ForkEvent: `Сделан fork`, CreateEvent: `Создано в`, ReleaseEvent: `Опубликован релиз для` } : { PushEvent: `Pushed commits to`, PullRequestEvent: `Updated pull request in`, IssuesEvent: `Updated issue in`, WatchEvent: `Starred`, ForkEvent: `Forked`, CreateEvent: `Created in`, ReleaseEvent: `Published release for` }; return [dict[e.type as keyof typeof dict] || e.type.replace(/Event$/,''), repo] as const; }
function base64(bytes: Uint8Array) { let s=''; const chunk=0x8000; for(let i=0;i<bytes.length;i+=chunk)s+=String.fromCharCode(...bytes.subarray(i,i+chunk)); return btoa(s); }
function textBase64(value: string) { const bytes = new TextEncoder().encode(value); return base64(bytes); }
function decodeBase64(value: string) { const bin=atob(value.replace(/\s/g,'')); const bytes=Uint8Array.from(bin,c=>c.charCodeAt(0)); return new TextDecoder().decode(bytes); }

async function github<T>(path: string, init: RequestInit = {}, token = ''): Promise<T> {
  const headers = new Headers(init.headers);
  headers.set('Accept','application/vnd.github+json'); headers.set('X-GitHub-Api-Version',API_VERSION); if (token) headers.set('Authorization',`Bearer ${token}`); if (init.body && !headers.has('Content-Type')) headers.set('Content-Type','application/json');
  const res = await fetch(`${API}${path}`, {...init, headers});
  if (!res.ok) { let message=`GitHub ${res.status}`; try { const body=await res.json() as {message?:string;documentation_url?:string}; if(body.message) message += `: ${body.message}`; } catch {} throw new Error(message); }
  if (res.status===204) return undefined as T; return res.json() as Promise<T>;
}

async function githubGraphQL<T>(query: string, variables: Record<string, unknown>, token: string): Promise<T> {
  const res = await fetch('https://api.github.com/graphql', {
    method: 'POST',
    headers: {
      Accept: 'application/vnd.github+json',
      'Content-Type': 'application/json',
      'X-GitHub-Api-Version': API_VERSION,
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
    },
    body: JSON.stringify({ query, variables }),
  });
  const payload = await res.json() as { data?: T; errors?: Array<{ message: string }> };
  if (!res.ok || payload.errors?.length) throw new Error(payload.errors?.[0]?.message || `GitHub GraphQL ${res.status}`);
  if (!payload.data) throw new Error('GitHub returned no GraphQL data.');
  return payload.data;
}

async function loadGithub() {
  const auth=readAuth(); if(!auth) throw new Error('GitHub is not connected.');
  const user=await github<GitHubUser>('/user',{},auth.token || undefined);
  const [repos, events] = await Promise.all([
    auth.token ? github<GitHubRepo[]>('/user/repos?per_page=100&sort=updated&direction=desc&visibility=all',{},auth.token) : github<GitHubRepo[]>(`/users/${encodeURIComponent(user.login)}/repos?per_page=100&sort=updated&direction=desc&type=owner`),
    github<GitHubEvent[]>(`/users/${encodeURIComponent(user.login)}/events/public?per_page=100`),
  ]);
  return {user,repos,events,fetchedAt:new Date().toISOString()};
}

function GitHubMark({size=18}:{size?:number}) { return <svg width={size} height={size} viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M12 .5C5.65.5.5 5.65.5 12a11.5 11.5 0 0 0 7.86 10.92c.58.1.79-.25.79-.56v-2.18c-3.2.7-3.88-1.35-3.88-1.35-.52-1.32-1.27-1.67-1.27-1.67-1.04-.71.08-.7.08-.7 1.15.08 1.75 1.18 1.75 1.18 1.02 1.74 2.67 1.24 3.32.95.1-.74.4-1.24.72-1.53-2.56-.29-5.26-1.28-5.26-5.71 0-1.26.45-2.29 1.18-3.1-.12-.29-.51-1.46.11-3.04 0 0 .96-.3 3.15 1.18a10.9 10.9 0 0 1 5.74 0c2.19-1.48 3.15-1.18 3.15-1.18.62 1.58.23 2.75.11 3.04.73.81 1.18 1.84 1.18 3.1 0 4.44-2.71 5.42-5.29 5.7.41.36.78 1.07.78 2.16v3.2c0 .31.21.67.8.56A11.5 11.5 0 0 0 23.5 12C23.5 5.65 18.35.5 12 .5Z"/></svg>; }

function usePrefs(){ const [prefs,setPrefs]=useState<Prefs>(()=>readPrefs()); useEffect(()=>{const on=()=>setPrefs(readPrefs()); window.addEventListener('devdock:prefs',on); return()=>window.removeEventListener('devdock:prefs',on)},[]); return prefs; }
function useGithubData(intervalMs:number){ const [data,setData]=useState<Awaited<ReturnType<typeof loadGithub>>|null>(null); const [error,setError]=useState(''); const [loading,setLoading]=useState(false); const refresh=useCallback(async()=>{if(!readAuth()){setData(null);setError('');return;} setLoading(true); try{setData(await loadGithub());setError('')}catch(e){setError(e instanceof Error?e.message:'GitHub request failed')}finally{setLoading(false)}},[]); useEffect(()=>{void refresh(); const on=()=>void refresh(); window.addEventListener('devdock:auth',on); const id=window.setInterval(()=>{if(document.visibilityState==='visible')void refresh()},intervalMs); return()=>{window.removeEventListener('devdock:auth',on);window.clearInterval(id)}},[intervalMs,refresh]); return {data,error,loading,refresh}; }

function Shell(){
  const prefs=usePrefs(); const t=copy[prefs.language]; const loc=useLocation(); const nav=useNavigate(); const [mobile,setMobile]=useState(false);
  const links=[['/',t.overview],['/repositories',t.repos],['/activity',t.activity],['/search',t.search],['/settings',t.settings]];
  return <div className={`site-shell ${prefs.theme==='light'?'theme-light':''}`}><header className="site-nav"><div className="nav-inner"><Link to="/" className="brand"><span className="brand-mark"><Code2 size={16}/></span><b>devdock</b></Link><nav className="nav-links">{links.map(([href,label])=><Link key={href} to={href} className={loc.pathname===href?'active':''}>{label}</Link>)}</nav><div className="nav-actions"><button className="nav-search" onClick={()=>nav('/search')}><Search size={14}/><span className="kbd">⌘K</span>{t.search}</button><button className="icon-button" title={t.language} onClick={()=>writePrefs({...prefs,language:prefs.language==='ru'?'en':'ru'})}><Globe size={15}/></button><button className="icon-button" title={t.theme} onClick={()=>writePrefs({...prefs,theme:prefs.theme==='dark'?'light':'dark'})}>{prefs.theme==='dark'?<Sun size={15}/>:<Moon size={15}/>}</button></div><button className="mobile-menu icon-button" onClick={()=>setMobile(v=>!v)}>{mobile?<X size={17}/>:<Menu size={17}/>}</button></div>{mobile&&<div className="mobile-links">{links.map(([href,label])=><Link key={href} to={href} onClick={()=>setMobile(false)}>{label}</Link>)}</div>}</header><main className="page-wrap"><Routes><Route path="/" element={<Dashboard t={t} prefs={prefs}/>}/><Route path="/repositories" element={<Repositories t={t} />}/><Route path="/repositories/:owner/:name" element={<RepositoryDetail t={t} />}/><Route path="/activity" element={<ActivityPage t={t}/>}/><Route path="/search" element={<GlobalSearch t={t}/>}/><Route path="/users/:login" element={<UserProfile t={t}/>}/><Route path="/settings" element={<SettingsPage t={t} prefs={prefs}/>}/></Routes></main></div>;
}
function SectionTitle({eyebrow,title,description,action}:{eyebrow:string;title:string;description:string;action?:ReactNode}){return <div className="section-heading"><span className="eyebrow">{eyebrow}</span><div className="heading-row"><div><h1>{title}</h1><p>{description}</p></div>{action}</div></div>}
function ConnectionBanner({t,error}:{t:Copy;error?:string}){const nav=useNavigate(); return <div className={`connection-banner glass-card ${error?'has-error':''}`}><div><div className="connection-title"><GitHubMark size={15}/> GitHub</div><p>{error||t.notConnected}</p></div><button className="action-button" onClick={()=>nav('/settings')}>{t.connect} <ArrowUpRight size={14}/></button></div>}

function Dashboard({t,prefs}:{t:Copy;prefs:Prefs}){const gh=useGithubData(prefs.pollMs); const data=gh.data; const repos=data?.repos.filter(r=>!r.fork)||[]; const stars=repos.reduce((s,r)=>s+r.stargazers_count,0); const forks=repos.reduce((s,r)=>s+r.forks_count,0); const monthly=useMemo(()=>Array.from({length:12},(_,m)=>data?.events.filter(e=>new Date(e.created_at).getMonth()===m).length||0),[data?.events]); const max=Math.max(1,...monthly); const recent=data?.events.slice(0,6)||[]; return <div className="dashboard-stack">{!data&&<ConnectionBanner t={t} error={gh.error}/>}<section className="hero-grid"><article className="glass-card profile-card glow-card"><div className="eyebrow">{data?`${t.live} GITHUB WORKSPACE`:'DEVD0CK WORKSPACE'}</div><div className="profile-grid">{data?<img className="profile-avatar" src={data.user.avatar_url} alt=""/>:<div className="profile-orb"><GitHubMark size={31}/></div>}<div><div className="status-line"><span className="status-dot"/>{data?`${t.connected} @${data.user.login}`:t.notConnected}</div><h1>{data?(data.user.name||data.user.login):'Developer Dashboard'}</h1><p>{data?.user.bio||t.signInHint}</p></div></div>{data&&<div className="profile-meta"><div><small>{t.repositoriesShort}</small><strong>{repos.length}</strong></div><div><small>{t.followers}</small><strong>{data.user.followers}</strong></div><div><small>{t.following}</small><strong>{data.user.following}</strong></div></div>}<div className="profile-actions">{data&&<><Link className="ghost-link" to={`/users/${data.user.login}`}>{t.openProfile}<ArrowUpRight size={13}/></Link><button className="ghost-link" onClick={()=>gh.refresh()}><RefreshCw size={13} className={gh.loading?'spin':''}/>{t.refresh}</button></>}</div></article><article className="glass-card side-card glow-card"><div className="side-top"><span className="eyebrow">{t.stats}</span><span className="mini-code">{data?`@${data.user.login}`:'—'}</span></div><div className="metric-big">{data?stars.toLocaleString():'—'}</div><div className="metric-label">{t.stars}</div><div className="mini-stats"><div><strong>{data?forks:'—'}</strong><small>{t.forks}</small></div><div><strong>{data?repos.length:'—'}</strong><small>{t.repositoriesShort}</small></div><div><strong>{data?data.events.length:'—'}</strong><small>{t.events}</small></div></div></article></section><section className="stats-grid">{[{v:repos.length,l:t.repositoriesShort,I:Zap},{v:stars,l:t.stars,I:Star},{v:forks,l:t.forks,I:GitFork},{v:data?.user.followers||0,l:t.followers,I:Users}].map(({v,l,I})=><article key={l} className="glass-card stat-card tilt-card glow-card"><I size={15}/><strong>{data?v.toLocaleString():'—'}</strong><small>{l}</small></article>)}</section><section className="content-grid"><article className="glass-card chart-card glow-card"><div className="card-head"><div><h2>{t.activityFlow}</h2><p>{t.publicEvents}</p></div><span className="muted-pill"><span className="status-dot"/>{data?t.live:t.waiting}</span></div><div className="chart">{monthly.map((n,i)=><div className="bar" key={i} style={{height:`${data?Math.max(8,n/max*100):8}%`}} title={`${n} events`}/>)}</div><div className="chart-labels"><span>Jan</span><span>Mar</span><span>May</span><span>Jul</span><span>Sep</span><span>Dec</span></div></article><article className="glass-card glow-card latest-activity-card"><div className="card-head"><div><h2>{t.latest}</h2><p>{data?t.realData:t.notConnected}</p></div><Link to="/activity" className="text-link">{t.activity} →</Link></div><div className="activity-list">{recent.map(e=>{const [lead,detail]=eventText(e,prefs.language);return <div className="activity-row" key={e.id}><span className="timeline-dot"/><div><p>{lead} <b>{detail}</b></p><small>{relative(e.created_at)}</small></div></div>})}{!recent.length&&<div className="empty-copy">{t.noEvents}</div>}</div></article></section><section><div className="section-bar"><div><h2>{t.featured}</h2><p>{t.realData}</p></div><Link to="/repositories" className="text-link">{t.allRepos} →</Link></div><div className="repo-grid">{repos.slice(0,4).map(r=><RepoCard key={r.id} repo={r} t={t}/>)}{data&&!repos.length&&<div className="empty-state glass-card">{t.noData}</div>}</div></section></div>}

function RepoCard({repo,t}:{repo:GitHubRepo;t:Copy}){const [flipped,setFlipped]=useState(false); return <article className={`project-card glow-card ${flipped?'is-flipped':''}`} onClick={()=>setFlipped(v=>!v)} tabIndex={0} onKeyDown={e=>{if(e.key==='Enter'||e.key===' ')setFlipped(v=>!v)}}><div className="project-inner"><div className="project-face glass-card project-front"><div><div className="project-visual"><span/><span/><span/></div><span className="eyebrow">{repo.private?t.privateLabel:t.publicLabel}</span><h3>{repo.name}</h3><p>{repo.description||t.noDescription}</p><div className="tag-row"><span className="tag">{repo.language||'—'}</span><span className="tag"><Star size={11}/>{repo.stargazers_count}</span><span className="tag"><GitFork size={11}/>{repo.forks_count}</span></div></div><span className="flip-hint">{flipped?'':'Click to view details'}</span></div><div className="project-face glass-card project-back"><div><span className="eyebrow">{t.repository}</span><h3>{repo.full_name}</h3><p>{repo.description||t.noDescription}</p><div className="detail-list-like"><div><span>{t.branch}</span><b>{repo.default_branch}</b></div><div><span>{t.issues}</span><b>{repo.open_issues_count}</b></div><div><span>{t.watchers}</span><b>{repo.watchers_count}</b></div><div><span>{t.permissions}</span><b>{repo.permissions?.push?'write':'read'}</b></div></div></div><div className="profile-actions"><Link className="ghost-link" to={`/repositories/${repo.full_name.split('/')[0]}/${repo.name}`} onClick={e=>e.stopPropagation()}>{t.openProfile} <ArrowUpRight size={13}/></Link><RepoActions repo={repo} t={t} onChange={()=>{}}/><a className="ghost-link" href={repo.html_url} target="_blank" rel="noreferrer" onClick={e=>e.stopPropagation()}>{t.openGithub}<ArrowUpRight size={13}/></a></div></div></div></article>}

function Repositories({t}:{t:Copy}){const prefs=usePrefs(); const gh=useGithubData(prefs.pollMs); const [q,setQ]=useState(''); const [privateOnly,setPrivateOnly]=useState(false); const repos=gh.data?.repos.filter(r=>!r.fork).filter(r=>!privateOnly||r.private)||[]; const filtered=repos.filter(r=>`${r.name} ${r.description||''}`.toLowerCase().includes(q.toLowerCase())); return <div><SectionTitle eyebrow="Workspace" title={t.repos} description={t.realData}/>{!gh.data&&<ConnectionBanner t={t} error={gh.error}/>}<div className="toolbar glass-card"><div className="search-field"><Search size={15}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder={`${t.search}...`}/></div><button className={`filter-toggle ${privateOnly?'selected':''}`} onClick={()=>setPrivateOnly(v=>!v)}><Lock size={13}/>{t.private}</button><button className="filter-toggle" onClick={()=>gh.refresh()}><RefreshCw size={13} className={gh.loading?'spin':''}/>{t.refresh}</button></div><div className="repo-grid repo-grid-all">{filtered.map(r=><RepoCard key={r.id} repo={r} t={t}/>)}{gh.data&&!filtered.length&&<div className="empty-state glass-card">{t.noData}</div>}</div></div>}

async function downloadRepository(repo: GitHubRepo, token: string) {
  const response = await fetch(`${API}/repos/${repo.full_name}/zipball/${encodeURIComponent(repo.default_branch)}`, {
    headers: { Accept: 'application/vnd.github+json', 'X-GitHub-Api-Version': API_VERSION, ...(token ? { Authorization: `Bearer ${token}` } : {}) },
  });
  if (!response.ok) throw new Error(`Download failed: GitHub ${response.status}`);
  const blob = await response.blob();
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = `${repo.name}-${repo.default_branch}.zip`;
  document.body.appendChild(a); a.click(); a.remove(); URL.revokeObjectURL(url);
}

function RepositoryDetail({t}:{t:Copy}){const {owner='',name=''}=useParams(); const [repo,setRepo]=useState<GitHubRepo|null>(null); const [tab,setTab]=useState<'files'|'issues'|'pulls'|'releases'>('files'); const [branch,setBranch]=useState(''); const [contents,setContents]=useState<RepoContent[]>([]); const [path,setPath]=useState(''); const [error,setError]=useState(''); const [loading,setLoading]=useState(false); const token=readAuth()?.token||'';
  const loadRepo=useCallback(async()=>{if(!owner||!name)return;setLoading(true);try{const r=await github<GitHubRepo>(`/repos/${encodeURIComponent(owner)}/${encodeURIComponent(name)}`,{},token);setRepo(r);setBranch(r.default_branch);setError('');}catch(e){setError(e instanceof Error?e.message:'Repository failed')}finally{setLoading(false)}},[owner,name,token]);
  const loadContents=useCallback(async(p=path,b=branch)=>{if(!repo)return;setLoading(true);try{const value=await github<RepoContent|RepoContent[]>(`/repos/${repo.full_name}/contents/${p.split('/').filter(Boolean).map(encodeURIComponent).join('/')}?ref=${encodeURIComponent(b||repo.default_branch)}`,{},token);setContents(Array.isArray(value)?value:[value]);setPath(p);setError('')}catch(e){setError(e instanceof Error?e.message:'Contents failed')}finally{setLoading(false)}},[repo,branch,path,token]);
  useEffect(()=>{void loadRepo()},[loadRepo]); useEffect(()=>{if(repo)void loadContents('',branch||repo.default_branch)},[repo]);
  return <div><Link to="/repositories" className="back-link">← {t.repos}</Link>{error&&<div className="settings-error">{error}</div>}{repo&&<><section className="glass-card detail-hero"><div><span className="eyebrow">{repo.private?t.privateLabel:t.publicLabel}</span><h1>{repo.full_name}</h1><p>{repo.description||t.noDescription}</p></div><div className="profile-actions"><button className="ghost-link" onClick={async()=>{try{await downloadRepository(repo,token)}catch(e){setError(e instanceof Error?e.message:'Download failed')}}}><Download size={13}/>{t.downloadZip}</button><a className="ghost-link" href={repo.html_url} target="_blank" rel="noreferrer">{t.openGithub}<ArrowUpRight size={13}/></a><RepoActions repo={repo} t={t} onChange={loadRepo}/></div></section><div className="detail-stats glass-card"><div><small>{t.stars}</small><strong>{repo.stargazers_count}</strong></div><div><small>{t.forks}</small><strong>{repo.forks_count}</strong></div><div><small>{t.issues}</small><strong>{repo.open_issues_count}</strong></div><div><small>{t.branch}</small><strong>{repo.default_branch}</strong></div></div><div className="tabs glass-card">{[['files',t.files],['issues',t.issues],['pulls',t.pulls],['releases',t.releases]].map(([k,v])=><button key={k} className={tab===k?'active':''} onClick={()=>setTab(k as typeof tab)}>{v}</button>)}</div>{tab==='files'&&<FileBrowser repo={repo} t={t} token={token} branch={branch} setBranch={setBranch} contents={contents} path={path} loading={loading} onOpen={p=>loadContents(p,branch)} onRefresh={()=>loadContents(path,branch)}/>} {tab==='issues'&&<IssueList repo={repo} t={t} token={token}/>} {tab==='pulls'&&<PullList repo={repo} t={t} token={token}/>} {tab==='releases'&&<ReleaseList repo={repo} t={t} token={token}/>}</>}</div>}

function RepoActions({repo,t,onChange}:{repo:GitHubRepo;t:Copy;onChange:()=>void}){const token=readAuth()?.token||''; const [starred,setStarred]=useState(false); const [watched,setWatched]=useState(false); const [busy,setBusy]=useState(false); useEffect(()=>{if(!token)return; void github(`/user/starred/${repo.full_name}`,{},token).then(()=>setStarred(true)).catch(()=>setStarred(false)); void github<{subscribed:boolean}>(`/repos/${repo.full_name}/subscription`,{},token).then(v=>setWatched(v.subscribed)).catch(()=>{});},[repo.full_name,token]); const toggleStar=async()=>{if(!token)return;setBusy(true);try{await github(`/user/starred/${repo.full_name}`,{method:starred?'DELETE':'PUT'},token);setStarred(!starred);onChange()}finally{setBusy(false)}}; const toggleWatch=async()=>{if(!token)return;setBusy(true);try{if(watched)await github(`/repos/${repo.full_name}/subscription`,{method:'DELETE'},token);else await github(`/repos/${repo.full_name}/subscription`,{method:'PUT',body:JSON.stringify({subscribed:true,ignored:false})},token);setWatched(!watched);onChange()}finally{setBusy(false)}}; return <div className="inline-actions"><button className="action-button" disabled={busy||!token} onClick={toggleStar}><Star size={13}/>{starred?t.unstar:t.star}</button><button className="action-button" disabled={busy||!token} onClick={toggleWatch}><Eye size={13}/>{watched?t.unwatch:t.watch}</button></div>}

function FileBrowser({repo,t,token,branch,setBranch,contents,path,loading,onOpen,onRefresh}:{repo:GitHubRepo;t:Copy;token:string;branch:string;setBranch:(x:string)=>void;contents:RepoContent[];path:string;loading:boolean;onOpen:(p:string)=>void;onRefresh:()=>void}){
  const [edit,setEdit]=useState<RepoContent|null>(null);
  const [image,setImage]=useState<RepoContent|null>(null);
  const [branches,setBranches]=useState<string[]>([]);
  useEffect(()=>{void github<Array<{name:string}>>(`/repos/${repo.full_name}/branches?per_page=100`,{},token).then(v=>setBranches(v.map(b=>b.name))).catch(()=>setBranches([repo.default_branch]))},[repo.full_name,token]);
  const isImage=(item:RepoContent)=>/\.(png|jpe?g|gif|webp|svg|bmp|ico|avif)$/i.test(item.name);
  return <section className="glass-card browser-card"><div className="browser-head"><div><span className="eyebrow">{t.files}</span><div className="crumbs"><button onClick={()=>onOpen('')}>{t.root}</button>{path&&path.split('/').map((part,i)=>{const p=path.split('/').slice(0,i+1).join('/');return <span key={p}><ChevronRight size={12}/><button onClick={()=>onOpen(p)}>{part}</button></span>})}</div></div><div className="browser-tools"><select value={branch} onChange={e=>{setBranch(e.target.value);}}>{branches.map(b=><option key={b}>{b}</option>)}</select><button className="icon-button" onClick={onRefresh} title={t.refresh}><RefreshCw size={14} className={loading?'spin':''}/></button></div></div><div className="file-list">{contents.map(item=>item.type==='dir'?<button key={item.path} className="file-row" onClick={()=>onOpen(item.path)}><FolderIcon/><span>{item.name}</span><ChevronRight size={13}/></button>:<button key={item.path} className="file-row" onClick={()=>isImage(item)?setImage(item):setEdit(item)}><File size={14}/><span>{item.name}</span><small>{item.size} b</small>{isImage(item)&&<span className="file-kind">IMG</span>}</button>)}{!contents.length&&!loading&&<div className="empty-state">{t.emptyFolder}</div>}</div>{edit&&<FileModal repo={repo} item={edit} t={t} token={token} branch={branch} onClose={()=>setEdit(null)} onSaved={onRefresh}/>} {image&&<ImageModal repo={repo} item={image} t={t} token={token} branch={branch} onClose={()=>setImage(null)}/>}</section>
}
function ImageModal({repo,item,t,token,branch,onClose}:{repo:GitHubRepo;item:RepoContent;t:Copy;token:string;branch:string;onClose:()=>void}){const [src,setSrc]=useState(item.download_url||'');const [error,setError]=useState('');useEffect(()=>{let objectUrl='';let active=true;(async()=>{try{const r=await fetch(`${API}/repos/${repo.full_name}/contents/${item.path}?ref=${encodeURIComponent(branch)}`,{headers:{Accept:'application/vnd.github+json','X-GitHub-Api-Version':API_VERSION,...(token?{Authorization:`Bearer ${token}`}:{})}});if(!r.ok)throw new Error(`GitHub ${r.status}`);const v=await r.json() as RepoContent;if(v.content&&v.encoding==='base64'){const bin=atob(v.content.replace(/\s/g,''));const bytes=Uint8Array.from(bin,c=>c.charCodeAt(0));const blob=new Blob([bytes]);objectUrl=URL.createObjectURL(blob);if(active)setSrc(objectUrl)}}catch(e){if(active)setError(e instanceof Error?e.message:'Image load failed')}})();return()=>{active=false;if(objectUrl)URL.revokeObjectURL(objectUrl)}},[repo.full_name,item.path,branch,token]);return <div className="modal-backdrop"><div className="modal-card glass-card image-modal"><div className="modal-head"><div><span className="eyebrow">{t.imageFile}</span><h3>{item.path}</h3></div><button className="icon-button" onClick={onClose}><X size={15}/></button></div>{error?<div className="settings-error">{error}</div>:src?<img src={src} alt={item.name} className="image-preview"/>:<div className="empty-state">{t.loading}</div>}<div className="modal-actions"><a className="action-button" href={item.html_url} target="_blank" rel="noreferrer">{t.openGithub}</a><button className="action-button" onClick={onClose}>{t.close}</button></div></div></div>}

function FolderIcon(){return <span className="folder-mark"><span/></span>}

function FileModal({repo,item,t,token,branch,onClose,onSaved}:{repo:GitHubRepo;item:RepoContent;t:Copy;token:string;branch:string;onClose:()=>void;onSaved:()=>void}){const [content,setContent]=useState('');const [message,setMessage]=useState(`Update ${item.path}`);const [sha,setSha]=useState(item.sha);const [loading,setLoading]=useState(false);const [status,setStatus]=useState(''); useEffect(()=>{void github<RepoContent>(`/repos/${repo.full_name}/contents/${item.path}?ref=${encodeURIComponent(branch)}`,{},token).then(v=>{setContent(v.content&&v.encoding==='base64'?decodeBase64(v.content):'');setSha(v.sha)}).catch(e=>setStatus(e instanceof Error?e.message:'Failed to load file'))},[repo.full_name,item.path,branch,token]); const save=async(e:FormEvent)=>{e.preventDefault();if(!token){setStatus('Token required.');return;}setLoading(true);try{await github(`/repos/${repo.full_name}/contents/${item.path}`,{method:'PUT',body:JSON.stringify({message,content:textBase64(content),sha,branch})},token);setStatus(t.success);onSaved()}catch(err){setStatus(err instanceof Error?err.message:'Save failed')}finally{setLoading(false)}}; const remove=async()=>{if(!token)return;setLoading(true);try{await github(`/repos/${repo.full_name}/contents/${item.path}`,{method:'DELETE',body:JSON.stringify({message:`Delete ${item.path}`,sha,branch})},token);onSaved();onClose()}catch(err){setStatus(err instanceof Error?err.message:'Delete failed')}finally{setLoading(false)}}; return <div className="modal-backdrop"><div className="modal-card glass-card"><div className="modal-head"><div><span className="eyebrow">{t.editor}</span><h3>{item.path}</h3></div><button className="icon-button" onClick={onClose}><X size={15}/></button></div><form onSubmit={save}><textarea className="code-editor" value={content} onChange={e=>setContent(e.target.value)} spellCheck={false}/><input value={message} onChange={e=>setMessage(e.target.value)} placeholder={t.message}/><div className="modal-actions"><button className="action-button primary" disabled={loading}><Save size={13}/>{t.saveFile}</button><button type="button" className="action-button danger" disabled={loading} onClick={remove}><Trash2 size={13}/>{t.deleteFile}</button>{status&&<span className="form-status">{status}</span>}</div></form></div></div>}

function IssueList({repo,t,token}:{repo:GitHubRepo;t:Copy;token:string}){const [items,setItems]=useState<GitHubIssue[]>([]);const [show,setShow]=useState(false);const [title,setTitle]=useState('');const [body,setBody]=useState('');const refresh=useCallback(()=>void github<GitHubIssue[]>(`/repos/${repo.full_name}/issues?state=open&per_page=50`,{},token).then(setItems).catch(()=>setItems([])),[repo.full_name,token]);useEffect(()=>{refresh()},[refresh]);const create=async(e:FormEvent)=>{e.preventDefault();if(!token)return;await github(`/repos/${repo.full_name}/issues`,{method:'POST',body:JSON.stringify({title,body})},token);setTitle('');setBody('');setShow(false);refresh()};return <section className="glass-card list-card"><div className="card-head"><div><h2>{t.issues}</h2><p>{items.length} open</p></div><button className="action-button primary" onClick={()=>setShow(v=>!v)}><Plus size={13}/>{t.newIssue}</button></div>{show&&<form className="composer compact" onSubmit={create}><input required value={title} onChange={e=>setTitle(e.target.value)} placeholder={t.issueTitle}/><textarea required value={body} onChange={e=>setBody(e.target.value)} placeholder={t.issueBody}/><button className="action-button primary">{t.create}</button></form>}<div className="data-list">{items.map(i=><a key={i.id} className="data-row" href={i.html_url} target="_blank" rel="noreferrer"><CircleDot size={14}/><div><strong>#{i.number} {i.title}</strong><small>{i.user.login} · {relative(i.updated_at)}</small></div><ArrowUpRight size={13}/></a>)}{!items.length&&<div className="empty-state">{t.noData}</div>}</div></section>}

function PullList({repo,t,token}:{repo:GitHubRepo;t:Copy;token:string}){const [items,setItems]=useState<GitHubPull[]>([]);const [show,setShow]=useState(false);const [title,setTitle]=useState('');const [head,setHead]=useState('');const [base,setBase]=useState(repo.default_branch);const [body,setBody]=useState('');const refresh=useCallback(()=>void github<GitHubPull[]>(`/repos/${repo.full_name}/pulls?state=open&per_page=50`,{},token).then(setItems).catch(()=>setItems([])),[repo.full_name,token]);useEffect(()=>{refresh()},[refresh]);const create=async(e:FormEvent)=>{e.preventDefault();if(!token)return;await github(`/repos/${repo.full_name}/pulls`,{method:'POST',body:JSON.stringify({title,head,base,body})},token);setTitle('');setHead('');setBody('');setShow(false);refresh()};return <section className="glass-card list-card"><div className="card-head"><div><h2>{t.pulls}</h2><p>{items.length} open</p></div><button className="action-button primary" onClick={()=>setShow(v=>!v)}><GitPullRequest size={13}/>{t.createPull}</button></div>{show&&<form className="composer compact" onSubmit={create}><input required value={title} onChange={e=>setTitle(e.target.value)} placeholder={t.title}/><div className="form-grid-2"><input required value={head} onChange={e=>setHead(e.target.value)} placeholder={`${t.branch}: feature`}/><input required value={base} onChange={e=>setBase(e.target.value)} placeholder={t.branch}/></div><textarea value={body} onChange={e=>setBody(e.target.value)} placeholder={t.body}/><button className="action-button primary">{t.create}</button></form>}<div className="data-list">{items.map(i=><a key={i.id} className="data-row" href={i.html_url} target="_blank" rel="noreferrer"><GitPullRequest size={14}/><div><strong>#{i.number} {i.title}</strong><small>{i.user.login} · {relative(i.updated_at)}</small></div><ArrowUpRight size={13}/></a>)}{!items.length&&<div className="empty-state">{t.noData}</div>}</div></section>}

function ReleaseList({repo,t,token}:{repo:GitHubRepo;t:Copy;token:string}){const [items,setItems]=useState<GitHubRelease[]>([]);const [show,setShow]=useState(false);const [tag,setTag]=useState('v1.0.0');const [name,setName]=useState('');const [body,setBody]=useState('');useEffect(()=>{void github<GitHubRelease[]>(`/repos/${repo.full_name}/releases?per_page=20`,{},token).then(setItems).catch(()=>setItems([]))},[repo.full_name,token]);const create=async(e:FormEvent)=>{e.preventDefault();if(!token)return;const r=await github<GitHubRelease>(`/repos/${repo.full_name}/releases`,{method:'POST',body:JSON.stringify({tag_name:tag,name:name||tag,body,draft:false,prerelease:false})},token);setItems(x=>[r,...x]);setShow(false);setTag('v1.0.0');setName('');setBody('')};return <section className="glass-card list-card"><div className="card-head"><div><h2>{t.releases}</h2><p>GitHub releases</p></div><button className="action-button primary" onClick={()=>setShow(v=>!v)}><Plus size={13}/>{t.newRelease}</button></div>{show&&<form className="composer compact" onSubmit={create}><div className="form-grid-2"><input required value={tag} onChange={e=>setTag(e.target.value)} placeholder="v1.0.0"/><input value={name} onChange={e=>setName(e.target.value)} placeholder={t.title}/></div><textarea value={body} onChange={e=>setBody(e.target.value)} placeholder={t.body}/><button className="action-button primary">{t.create}</button></form>}<div className="data-list">{items.map(r=><a key={r.id} className="data-row" href={r.html_url} target="_blank" rel="noreferrer"><BookOpen size={14}/><div><strong>{r.tag_name}</strong><small>{r.name||''} · {r.published_at?relative(r.published_at):t.waiting}</small></div><ArrowUpRight size={13}/></a>)}{!items.length&&<div className="empty-state">{t.noData}</div>}</div></section>}

function ActivityPage({t}:{t:Copy}){const prefs=usePrefs();const gh=useGithubData(prefs.pollMs);return <div><SectionTitle eyebrow="Timeline" title={t.activity} description={t.publicEvents}/>{!gh.data&&<ConnectionBanner t={t} error={gh.error}/>}<section className="glass-card activity-full">{(gh.data?.events||[]).map(e=>{const [lead,detail]=eventText(e,prefs.language);return <div className="activity-row large" key={e.id}><span className="timeline-dot"/><div><p>{lead} <b>{detail}</b></p><small>{relative(e.created_at)}</small></div></div>})}{gh.data&&!gh.data.events.length&&<div className="empty-state">{t.noEvents}</div>}</section></div>}

function GlobalSearch({t}:{t:Copy}){const [kind,setKind]=useState<'repositories'|'users'>('repositories');const [q,setQ]=useState('');const [repoItems,setRepoItems]=useState<SearchRepo[]>([]);const [userItems,setUserItems]=useState<SearchUser[]>([]);const [loading,setLoading]=useState(false);const [error,setError]=useState('');const submit=async(e:FormEvent)=>{e.preventDefault();if(!q.trim())return;setLoading(true);setError('');try{const auth=readAuth();if(kind==='repositories'){const data=await github<{items:SearchRepo[]}>(`/search/repositories?q=${encodeURIComponent(q.trim())}&per_page=50`,{},auth?.token);setRepoItems(data.items)}else{const data=await github<{items:SearchUser[]}>(`/search/users?q=${encodeURIComponent(q.trim())}&per_page=50`,{},auth?.token);setUserItems(data.items)}}catch(e){setError(e instanceof Error?e.message:'Search failed')}finally{setLoading(false)}};return <div><SectionTitle eyebrow="Search" title={t.globalSearch} description={t.searchHint}/><div className="search-switcher glass-card"><button className={kind==='repositories'?'active':''} onClick={()=>setKind('repositories')}><BookOpen size={14}/>{t.repositories}</button><button className={kind==='users'?'active':''} onClick={()=>setKind('users')}><User size={14}/>{t.users}</button></div><form className="search-big glass-card" onSubmit={submit}><Search size={17}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder={t.searchHint}/><button className="action-button primary" disabled={loading}>{loading?<RefreshCw className="spin" size={13}/>:<Search size={13}/>} {t.find}</button></form>{error&&<div className="settings-error">{error}</div>}{kind==='repositories'?<div className="search-results">{repoItems.map(r=><Link key={r.id} className="search-result glass-card" to={`/repositories/${r.full_name.split('/')[0]}/${r.name}`}><div><span className="eyebrow">{r.private?t.private:r.language||t.repositories}</span><h3>{r.full_name}</h3><p>{r.description||t.noDescription}</p></div><div className="result-meta"><span>{r.language||'—'}</span><span><Star size={12}/>{r.stargazers_count}</span><span><GitFork size={12}/>{r.forks_count}</span><ArrowUpRight size={14}/></div></Link>)}{q&&!loading&&!repoItems.length&&!error&&<div className="empty-state glass-card">{t.noData}</div>}</div>:<div className="search-results">{userItems.map(u=><Link key={u.id} className="search-result glass-card" to={`/users/${u.login}`}><div className="user-result-main"><img src={u.avatar_url} alt=""/><div><span className="eyebrow">{t.users}</span><h3>@{u.login}</h3><p>{u.type}</p></div></div><div className="result-meta"><span>{u.type}</span><ArrowUpRight size={14}/></div></Link>)}{q&&!loading&&!userItems.length&&!error&&<div className="empty-state glass-card">{t.noData}</div>}</div>}</div>}

function UserProfile({t}:{t:Copy}){
  const {login=''}=useParams(); const token=readAuth()?.token||'';
  const currentYear=new Date().getFullYear();
  const [selectedYear,setSelectedYear]=useState(currentYear);
  const [availableYears,setAvailableYears]=useState<number[]>([]);
  const [user,setUser]=useState<GitHubUser|null>(null); const [repos,setRepos]=useState<GitHubRepo[]>([]); const [events,setEvents]=useState<GitHubEvent[]>([]); const [following,setFollowing]=useState(false); const [busy,setBusy]=useState(false); const [error,setError]=useState(''); const [calendar,setCalendar]=useState<ContributionCalendar|null>(null); const [calendarLoading,setCalendarLoading]=useState(false);
  const loadUser=useCallback(async()=>{if(!login)return;setError('');try{const [u,r,e]=await Promise.all([github<GitHubUser>(`/users/${encodeURIComponent(login)}`,{},token),github<GitHubRepo[]>(`/users/${encodeURIComponent(login)}/repos?per_page=100&sort=updated&type=owner`,{},token),github<GitHubEvent[]>(`/users/${encodeURIComponent(login)}/events/public?per_page=100`,{},token)]);setUser(u);setRepos(r);setEvents(e)}catch(e){setError(e instanceof Error?e.message:'User load failed')}if(token)void github(`/user/following/${encodeURIComponent(login)}`,{},token).then(()=>setFollowing(true)).catch(()=>setFollowing(false))},[login,token]);
  const loadCalendar=useCallback(async(year:number)=>{if(!login)return;setCalendarLoading(true);try{const from=`${year}-01-01T00:00:00Z`;const to=`${year}-12-31T23:59:59Z`;const c=await githubGraphQL<{user:UserContributions}>(`query($login:String!,$from:DateTime!,$to:DateTime!){user(login:$login){contributionsCollection(from:$from,to:$to){contributionYears contributionCalendar{totalContributions weeks{contributionDays{date contributionCount color weekday}}}}}}`,{login,from,to},token);setCalendar(c.user.contributionsCollection.contributionCalendar);setAvailableYears(c.user.contributionsCollection.contributionYears);if(!c.user.contributionsCollection.contributionYears.includes(selectedYear)){const first=c.user.contributionsCollection.contributionYears[0];if(first)setSelectedYear(first)}}catch(e){setError(e instanceof Error?e.message:'Contribution graph unavailable')}finally{setCalendarLoading(false)}},[login,token,selectedYear]);
  useEffect(()=>{void loadUser()},[loadUser]);
  useEffect(()=>{void loadCalendar(selectedYear)},[loadCalendar,selectedYear]);
  const toggle=async()=>{if(!token||!user)return;setBusy(true);try{if(following)await github(`/user/following/${user.login}`,{method:'DELETE'},token);else await github(`/user/following/${user.login}`,{method:'PUT'},token);setFollowing(v=>!v)}finally{setBusy(false)}};
  if(error)return <div className="settings-error">{error}</div>;
  const days=calendar?.weeks.flatMap(w=>w.contributionDays)??[];
  const intensity=(n:number)=>n===0?'level-0':n<3?'level-1':n<6?'level-2':n<10?'level-3':'level-4';
  const [hoveredDay,setHoveredDay]=useState<ContributionDay|null>(null);
  const [hoverPoint,setHoverPoint]=useState({x:0,y:0});
  const activeLanguage=readPrefs().language;
  const contributionDate=(iso:string)=>new Intl.DateTimeFormat(activeLanguage==='ru'?'ru-RU':'en-US',{day:'numeric',month:'long',year:'numeric'}).format(new Date(`${iso}T00:00:00Z`));
  const contributionLabel=(d:ContributionDay)=>activeLanguage==='ru'
    ? `${d.contributionCount} ${d.contributionCount===1?'вклад':'вкладов'} · ${contributionDate(d.date)}`
    : `${d.contributionCount} ${d.contributionCount===1?'contribution':'contributions'} · ${contributionDate(d.date)}`;
  const popular=[...repos].filter(r=>!r.fork).sort((a,b)=>b.stargazers_count-a.stargazers_count).slice(0,6);
  return <div>{user&&<><Link to="/search" className="back-link">← {t.search}</Link><section className="glass-card detail-hero"><div className="user-profile-head"><img className="profile-avatar" src={user.avatar_url} alt=""/><div><span className="eyebrow">@{user.login}</span><h1>{user.name||user.login}</h1><p>{user.bio||t.noDescription}</p><div className="user-facts"><span>{user.public_repos} {t.repositoriesCount}</span><span>{user.followers} {t.followers}</span><span>{user.following} {t.following}</span>{user.location&&<span>{user.location}</span>}</div></div></div><div className="profile-actions"><button className="action-button" disabled={!token||busy} onClick={toggle}><Users size={13}/>{following?t.unfollow:t.follow}</button><button className="action-button" onClick={()=>{void loadUser();void loadCalendar(selectedYear)}}><RefreshCw size={13}/>{t.refresh}</button><a className="action-button" href={user.html_url} target="_blank" rel="noreferrer"><ArrowUpRight size={13}/>{t.openGithub}</a></div></section><section className="glass-card contribution-card"><div className="card-head contribution-head"><div><h2>{t.contributionGraph}</h2><p>{calendarLoading?'…':(calendar?.totalContributions.toLocaleString()||'0')} {t.contributionTotal}</p></div><div className="year-switcher" role="tablist" aria-label={t.contributionGraph}>{(availableYears.length?availableYears:Array.from({length:5},(_,i)=>currentYear-i)).map(year=><button key={year} type="button" className={selectedYear===year?'active':''} onClick={()=>setSelectedYear(year)}>{year}</button>)}</div></div><div className="contribution-scroll" aria-live="polite">{calendarLoading?<div className="contribution-loading">{t.loading}</div>:<div className="contribution-grid-wrap"><div className="contribution-grid">{days.map(d=><span key={d.date} tabIndex={0} className={`contribution-cell ${intensity(d.contributionCount)}`} aria-label={contributionLabel(d)} onMouseEnter={(e)=>{setHoveredDay(d);setHoverPoint({x:e.clientX,y:e.clientY})}} onMouseMove={(e)=>{setHoverPoint({x:e.clientX,y:e.clientY})}} onMouseLeave={()=>setHoveredDay(null)} onFocus={()=>setHoveredDay(d)} onBlur={()=>setHoveredDay(null)}/>)}</div>{hoveredDay && createPortal(
  <div
    className="contribution-tooltip contribution-tooltip-fixed contribution-tooltip-live"
    role="status"
    style={{ left: Math.min(hoverPoint.x + 14, window.innerWidth - 250), top: Math.max(hoverPoint.y - 12, 42) }}
  >
    <strong>{contributionLabel(hoveredDay)}</strong>
  </div>,
  document.body
)}</div>}</div><div className="contribution-legend"><span>Less</span><i className="contribution-cell level-0"/><i className="contribution-cell level-1"/><i className="contribution-cell level-2"/><i className="contribution-cell level-3"/><i className="contribution-cell level-4"/><span>More</span></div></section><section><div className="section-bar"><div><h2>{t.popularRepos}</h2><p>{t.realData}</p></div><Link to="/repositories" className="text-link">{t.allRepos} →</Link></div><div className="repo-grid repo-grid-all">{popular.map(r=><RepoCard key={r.id} repo={r} t={t}/>)}</div></section><section className="glass-card activity-profile"><div className="card-head"><div><h2>{t.contributionActivity}</h2><p>{t.publicEvents}</p></div><span className="muted-pill">{events.length}</span></div><div className="activity-list">{events.slice(0,12).map(e=>{const activeLang = localStorage.getItem(PREFS_KEY) ? readPrefs().language : 'ru'; const [lead,detail]=eventText(e,activeLang);const [owner,repoName]=e.repo.name.split('/');const href=owner&&repoName?`/repositories/${owner}/${repoName}`:'';return href?<Link to={href} className="activity-row activity-link" key={e.id}><span className="timeline-dot"/><div><p>{lead} <b>{detail}</b></p><small>{relative(e.created_at)}</small></div><ArrowUpRight size={13}/></Link>:<div className="activity-row" key={e.id}><span className="timeline-dot"/><div><p>{lead} <b>{detail}</b></p><small>{relative(e.created_at)}</small></div></div>})}{!events.length&&<div className="empty-copy">{t.noEvents}</div>}</div></section></>}</div>
}

function SettingsPage({t,prefs}:{t:Copy;prefs:Prefs}){const gh=useGithubData(prefs.pollMs);const auth=readAuth();const [tab,setTab]=useState<'profile'|'repo'|'repo-settings'|'file'|'issue'|'release'|'gist'|'notifications'|'orgs'|'emails'|'keys'|'following'|'followers'|'starred'|'blocked'>('profile');const [username,setUsername]=useState(auth?.username||'');const [token,setToken]=useState(auth?.token||'');const [showToken,setShowToken]=useState(false);const [status,setStatus]=useState('');const [profile,setProfile]=useState({name:'',bio:'',location:'',company:'',blog:''});useEffect(()=>{if(gh.data)setProfile({name:gh.data.user.name||'',bio:gh.data.user.bio||'',location:gh.data.user.location||'',company:gh.data.user.company||'',blog:gh.data.user.blog||''})},[gh.data]);const save=()=>{writeAuth({username,token});setStatus(t.success)};const updateProfile=async(e:FormEvent)=>{e.preventDefault();if(!token){setStatus(t.writeHint);return;}try{const u=await github<GitHubUser>('/user',{method:'PATCH',body:JSON.stringify(profile)},token);setProfile({name:u.name||'',bio:u.bio||'',location:u.location||'',company:u.company||'',blog:u.blog||''});setStatus(t.success);gh.refresh()}catch(e){setStatus(e instanceof Error?e.message:'Profile update failed')}};const createRepo=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const form=new FormData(e.currentTarget);try{await github('/user/repos',{method:'POST',body:JSON.stringify({name:String(form.get('name')),description:String(form.get('description')||''),private:form.get('private')==='on',auto_init:true})},token);setStatus(t.success);gh.refresh()}catch(e){setStatus(e instanceof Error?e.message:'Create repository failed')}};return <div><SectionTitle eyebrow={t.settings} title={t.controlCenter} description={t.danger}/><div className="settings-layout"><aside className="settings-menu glass-card"><div className="settings-group-label">{t.accountSection}</div><button className={tab==='profile'?'active':''} onClick={()=>setTab('profile')}><User size={14}/>{t.profile}</button><button className={tab==='following'?'active':''} onClick={()=>setTab('following')}><Users size={14}/>{t.followingList}</button><button className={tab==='followers'?'active':''} onClick={()=>setTab('followers')}><Users size={14}/>{t.followersList}</button><button className={tab==='starred'?'active':''} onClick={()=>setTab('starred')}><Star size={14}/>{t.starredList}</button><button className={tab==='blocked'?'active':''} onClick={()=>setTab('blocked')}><Shield size={14}/>{t.blockedList}</button><button className={tab==='notifications'?'active':''} onClick={()=>setTab('notifications')}><Bell size={14}/>{t.notifications}</button><button className={tab==='orgs'?'active':''} onClick={()=>setTab('orgs')}><Users size={14}/>{t.organization}</button><button className={tab==='emails'?'active':''} onClick={()=>setTab('emails')}><Globe size={14}/>{t.emails}</button><button className={tab==='keys'?'active':''} onClick={()=>setTab('keys')}><KeyRound size={14}/>{t.keys}</button><button className={tab==='gist'?'active':''} onClick={()=>setTab('gist')}><BookOpen size={14}/>{t.gists}</button><div className="settings-group-label">{t.repositorySection}</div><button className={tab==='repo'?'active':''} onClick={()=>setTab('repo')}><Plus size={14}/>{t.createRepo}</button><button className={tab==='repo-settings'?'active':''} onClick={()=>setTab('repo-settings')}><Settings2 size={14}/>{t.repositorySettings}</button><button className={tab==='issue'?'active':''} onClick={()=>setTab('issue')}><CircleDot size={14}/>{t.issue}</button><button className={tab==='release'?'active':''} onClick={()=>setTab('release')}><BookOpen size={14}/>{t.releases}</button><button className={tab==='file'?'active':''} onClick={()=>setTab('file')}><File size={14}/>{t.editFile}</button><div className="settings-menu-footer"><span><Shield size={13}/>{t.localOnly}</span><small>{t.language}: {prefs.language.toUpperCase()}</small><small>{t.polling}: {prefs.pollMs/1000}s</small><small>{t.rateHint}</small></div></aside><section className="glass-card settings-card">
{tab==='profile'&&<div className="settings-section"><div className="oauth-hero"><div className="oauth-icon"><GitHubMark size={27}/></div><div><strong>{t.account}</strong><p>{t.localOnly}: credentials stay in this browser.</p></div></div><div className="credential-grid"><label className="field"><span>{t.username}</span><input value={username} onChange={e=>setUsername(e.target.value)} placeholder="your-username"/></label><label className="field"><span>{t.token}</span><div className="password-control"><input value={token} onChange={e=>setToken(e.target.value)} type={showToken?'text':'password'} placeholder="github_pat_..."/><button type="button" className="ghost-mini" onClick={()=>setShowToken(v=>!v)}>{showToken?'Hide':'Show'}</button></div></label></div><div className="setting-actions"><button className="action-button primary" onClick={save}><Save size={13}/>{t.save}</button>{auth&&<button className="action-button" onClick={()=>{clearAuth();setUsername('');setToken('');setStatus('')}}><LogOut size={13}/>{t.disconnect}</button>}{status&&<span className="form-status">{status}</span>}</div><div className="local-prefs"><div><span className="eyebrow">{t.localPreferences}</span><p>{t.localOnly}</p></div><div className="pref-controls"><div><small>{t.language}</small><div className="segmented">{(['ru','en'] as const).map(lang=><button key={lang} onClick={()=>writePrefs({...prefs,language:lang})} className={prefs.language===lang?'active':''}>{lang.toUpperCase()}</button>)}</div></div><div><small>{t.polling}</small><div className="segmented">{[1000,2000,3000].map(ms=><button key={ms} onClick={()=>writePrefs({...prefs,pollMs:ms as Prefs['pollMs']})} className={prefs.pollMs===ms?'active':''}>{ms/1000}s</button>)}</div></div></div></div>{gh.data&&<><div className="connected-profile"><img src={gh.data.user.avatar_url} alt=""/><div><strong>@{gh.data.user.login}</strong><span>{gh.data.user.name||gh.data.user.login}</span><small>{gh.data.user.followers} {t.followers} · {gh.data.user.public_repos} {t.repositoriesCount}</small></div><span className="status-good">● {t.connected}</span></div><form className="profile-form" onSubmit={updateProfile}><div className="section-bar"><div><h3>{t.profileEdit}</h3><p>{t.writeHint}</p></div></div><div className="form-grid-2"><label><span>{t.name}</span><input value={profile.name} onChange={e=>setProfile({...profile,name:e.target.value})}/></label><label><span>{t.company}</span><input value={profile.company} onChange={e=>setProfile({...profile,company:e.target.value})}/></label><label><span>{t.location}</span><input value={profile.location} onChange={e=>setProfile({...profile,location:e.target.value})}/></label><label><span>{t.website}</span><input value={profile.blog} onChange={e=>setProfile({...profile,blog:e.target.value})}/></label></div><label className="full-field"><span>{t.bio}</span><textarea value={profile.bio} onChange={e=>setProfile({...profile,bio:e.target.value})}/></label><button className="action-button primary"><Save size={13}/>{t.save}</button></form></>}</div>}
{tab==='repo'&&<form className="settings-section composer" onSubmit={createRepo}><span className="eyebrow">GitHub</span><h2>{t.createRepo}</h2><p>{t.writeHint}</p><label><span>{t.title}</span><input required name="name" placeholder="my-project"/></label><label><span>{t.description}</span><textarea name="description" placeholder={t.description}/></label><label className="check-row"><input name="private" type="checkbox"/><span>{t.private}</span></label><button className="action-button primary"><Plus size={13}/>{t.create}</button>{status&&<span className="form-status">{status}</span>}</form>}
{tab==='repo-settings'&&<RepositorySettings t={t} repos={gh.data?.repos.filter(r=>!r.fork)||[]} token={token} onSaved={gh.refresh}/>} 
{tab==='issue'&&<IssuePicker t={t} repos={gh.data?.repos.filter(r=>!r.fork)||[]} token={token}/>} 
{tab==='release'&&<ReleasePicker t={t} repos={gh.data?.repos.filter(r=>!r.fork)||[]} token={token}/>} 
{tab==='file'&&<StandaloneFileTool t={t} repos={gh.data?.repos.filter(r=>!r.fork)||[]} token={token}/>} 
{tab==='notifications'&&<Notifications t={t} token={token}/>} 
{tab==='following'&&<UserCollection t={t} token={token} mode="following"/>}{tab==='followers'&&<UserCollection t={t} token={token} mode="followers"/>}{tab==='starred'&&<UserCollection t={t} token={token} mode="starred"/>}{tab==='blocked'&&<UserCollection t={t} token={token} mode="blocked"/>}{tab==='orgs'&&<Organizations t={t} token={token}/>} 
{tab==='emails'&&<Emails t={t} token={token}/>} 
{tab==='keys'&&<Keys t={t} token={token}/>} 
{tab==='gist'&&<Gists t={t} token={token}/>} </section></div></div>}

function RepositorySettings({t,repos,token,onSaved}:{t:Copy;repos:GitHubRepo[];token:string;onSaved:()=>void}){const [name,setName]=useState(repos[0]?.full_name||'');const [desc,setDesc]=useState('');const [homepage,setHomepage]=useState('');const [privateRepo,setPrivateRepo]=useState(false);const [issues,setIssues]=useState(true);const [projects,setProjects]=useState(true);const [wiki,setWiki]=useState(true);const [discussions,setDiscussions]=useState(false);const [status,setStatus]=useState('');const selected=repos.find(r=>r.full_name===name)||repos[0];useEffect(()=>{if(!selected)return;setName(selected.full_name);setDesc(selected.description||'');setHomepage(selected.homepage||'');setPrivateRepo(selected.private);setIssues(selected.has_issues!==false);setProjects(selected.has_projects!==false);setWiki(selected.has_wiki!==false);setDiscussions(Boolean(selected.has_discussions))},[selected?.id]);const save=async(e:FormEvent)=>{e.preventDefault();if(!selected)return;try{await github(`/repos/${selected.full_name}`,{method:'PATCH',body:JSON.stringify({description:desc,homepage:homepage||null,private:privateRepo,has_issues:issues,has_projects:projects,has_wiki:wiki,has_discussions:discussions})},token);setStatus(t.success);onSaved()}catch(err){setStatus(err instanceof Error?err.message:'Update failed')}};return <form className="settings-section composer" onSubmit={save}>{selected?<><span className="eyebrow">GitHub</span><h2>{t.repositorySettings}</h2><label className="select-field"><span>{t.repository}</span><select value={selected.full_name} onChange={e=>setName(e.target.value)}>{repos.map(r=><option key={r.id}>{r.full_name}</option>)}</select></label><div className="form-grid-2"><label><span>{t.description}</span><input value={desc} onChange={e=>setDesc(e.target.value)}/></label><label><span>{t.homepage}</span><input value={homepage} onChange={e=>setHomepage(e.target.value)} placeholder="https://..."/></label></div><div className="settings-checks">{[['private',privateRepo,setPrivateRepo],[t.issues,issues,setIssues],[t.projects||'Projects',projects,setProjects],[t.wiki||'Wiki',wiki,setWiki],[t.discussions||'Discussions',discussions,setDiscussions]].map(([label,v,setter])=><label key={String(label)}><input type="checkbox" checked={Boolean(v)} onChange={e=>(setter as (v:boolean)=>void)(e.target.checked)}/><span>{String(label)}</span></label>)}</div><div className="composer-actions"><button className="action-button primary"><Save size={13}/>{t.save}</button>{status&&<span className="form-status">{status}</span>}</div></>:<div className="empty-state">{t.noData}</div>}</form>}
function IssuePicker({t,repos,token}:{t:Copy;repos:GitHubRepo[];token:string}){const [repo,setRepo]=useState(repos[0]?.full_name||'');const selected=repos.find(r=>r.full_name===repo)||repos[0];return selected?<IssueList repo={selected} t={t} token={token}/>:<div className="empty-state">{t.noData}</div>}
function ReleasePicker({t,repos,token}:{t:Copy;repos:GitHubRepo[];token:string}){const [repo,setRepo]=useState(repos[0]?.full_name||'');const selected=repos.find(r=>r.full_name===repo)||repos[0];return <div>{selected&&<div className="issue-select"><select value={selected.full_name} onChange={e=>setRepo(e.target.value)}>{repos.map(r=><option key={r.id}>{r.full_name}</option>)}</select></div>}{selected?<ReleaseList repo={selected} t={t} token={token}/>:<div className="empty-state">{t.noData}</div>}</div>}
function StandaloneFileTool({t,repos,token}:{t:Copy;repos:GitHubRepo[];token:string}){const [repo,setRepo]=useState(repos[0]?.full_name||'');const [branch,setBranch]=useState('');const [path,setPath]=useState('README.md');const [content,setContent]=useState('');const [sha,setSha]=useState('');const [message,setMessage]=useState('Update file');const [status,setStatus]=useState('');const selected=repos.find(r=>r.full_name===repo)||repos[0];useEffect(()=>{if(selected)setBranch(selected.default_branch)},[selected?.id]);const load=async()=>{if(!selected)return;try{const v=await github<RepoContent>(`/repos/${selected.full_name}/contents/${path}?ref=${encodeURIComponent(branch||selected.default_branch)}`,{},token);setContent(v.content&&v.encoding==='base64'?decodeBase64(v.content):'');setSha(v.sha);setStatus(t.loaded)}catch(e){setStatus(e instanceof Error?e.message:'Load failed')}};const save=async(e:FormEvent)=>{e.preventDefault();if(!selected)return;try{await github(`/repos/${selected.full_name}/contents/${path}`,{method:'PUT',body:JSON.stringify({message,content:textBase64(content),sha:sha||undefined,branch:branch||selected.default_branch})},token);setStatus(t.success)}catch(e){setStatus(e instanceof Error?e.message:'Save failed')}};const onPick=async(e:ChangeEvent<HTMLInputElement>)=>{const file=e.target.files?.[0];if(!file)return;setPath(file.name);setContent(await file.text());setSha('')};const onFolder=async(e:ChangeEvent<HTMLInputElement>)=>{if(!selected)return;const files=Array.from(e.target.files||[]);if(!files.length)return;let last='';for(const file of files){const rel=(file as File&{webkitRelativePath?:string}).webkitRelativePath||file.name;const body=await file.arrayBuffer();try{await github(`/repos/${selected.full_name}/contents/${rel}`,{method:'PUT',body:JSON.stringify({message:`Upload ${rel}`,content:base64(new Uint8Array(body)),branch:branch||selected.default_branch})},token);last=rel}catch(err){last=err instanceof Error?err.message:'upload failed';break}}setStatus(`${t.success}: ${last}`)};return <div className="settings-section file-tool"><div className="section-bar"><div><h3>{t.editFile}</h3><p>{t.uploadNote}</p></div></div><div className="issue-select"><select value={selected?.full_name||''} onChange={e=>setRepo(e.target.value)}>{repos.map(r=><option key={r.id}>{r.full_name}</option>)}</select></div>{selected&&<form className="composer" onSubmit={save}><div className="form-grid-2"><label><span>{t.branch}</span><input value={branch||selected.default_branch} onChange={e=>setBranch(e.target.value)}/></label><label><span>{t.path}</span><input value={path} onChange={e=>setPath(e.target.value)}/></label></div><label><span>{t.message}</span><input value={message} onChange={e=>setMessage(e.target.value)}/></label><textarea className="code-editor" value={content} onChange={e=>setContent(e.target.value)} spellCheck={false}/><div className="upload-row"><button type="button" className="file-picker"><Upload size={13}/>{t.uploadFile}<input type="file" onChange={onPick}/></button><button type="button" className="file-picker"><Upload size={13}/>{t.uploadFolder}<input type="file" multiple {...({webkitdirectory:'',directory:''} as React.InputHTMLAttributes<HTMLInputElement>)} onChange={onFolder}/></button><button type="button" className="action-button" onClick={load}><Download size={13}/>{t.viewer}</button></div><div className="composer-actions"><button className="action-button primary"><Save size={13}/>{t.saveFile}</button>{status&&<span className="form-status">{status}</span>}</div></form>}</div>}
function Notifications({t,token}:{t:Copy;token:string}){const [items,setItems]=useState<GitHubNotification[]>([]);const refresh=()=>void github<GitHubNotification[]>('/notifications?all=false&participating=false',{},token).then(setItems).catch(()=>setItems([]));useEffect(refresh,[]);const read=async(id:string)=>{await github(`/notifications/threads/${id}`,{method:'PATCH'},token);setItems(x=>x.filter(n=>n.id!==id))};return <div className="settings-section"><div className="section-bar"><div><h3>{t.notifications}</h3><p>{items.length} unread</p></div><button className="action-button" onClick={refresh}><RefreshCw size={13}/>{t.refresh}</button></div><div className="data-list">{items.map(n=><div className="data-row" key={n.id}><Bell size={14}/><div><strong>{n.subject.title}</strong><small>{n.repository.full_name} · {n.reason} · {relative(n.updated_at)}</small></div><button className="icon-button" onClick={()=>read(n.id)} title={t.markRead}><CheckCircle2 size={13}/></button></div>)}{!items.length&&<div className="empty-state">{t.noNotifications}</div>}</div></div>}
function UserCollection({t,token,mode}:{t:Copy;token:string;mode:'following'|'followers'|'starred'|'blocked'}){const [items,setItems]=useState<any[]>([]);const endpoint=mode==='following'?'/user/following':mode==='followers'?'/user/followers':mode==='starred'?'/user/starred':'/user/blocks';const title=mode==='following'?t.followingList:mode==='followers'?t.followersList:mode==='starred'?t.starredList:t.blockedList;const refresh=useCallback(()=>void github<any[]>(endpoint+'?per_page=100',{},token).then(setItems).catch(()=>setItems([])),[endpoint,token]);useEffect(()=>{refresh()},[refresh]);const remove=async(login:string)=>{try{if(mode==='following')await github(`/user/following/${encodeURIComponent(login)}`,{method:'DELETE'},token);else if(mode==='blocked')await github(`/user/blocks/${encodeURIComponent(login)}`,{method:'DELETE'},token);else return;await refresh()}catch{}};return <div className="settings-section"><div className="section-bar"><div><h3>{title}</h3><p>{items.length}</p></div><button className="action-button" onClick={refresh}><RefreshCw size={13}/>{t.refresh}</button></div><div className="data-list">{items.map((u:any)=>{const repoMode=mode==='starred';const href=repoMode?`/repositories/${u.owner?.login||u.full_name?.split('/')[0]}/${u.name}`:`/users/${u.login}`;return <Link key={u.id||u.login||u.full_name} className="data-row" to={href}><img src={repoMode&&u.owner?.avatar_url?u.owner.avatar_url:u.avatar_url} className="row-avatar" alt=""/><div><strong>{repoMode?u.full_name:`@${u.login}`}</strong><small>{repoMode?(u.description||t.noDescription):u.type||t.users}</small></div><ArrowUpRight size={13}/>{(mode==='following'||mode==='blocked')&&<button className="icon-button" onClick={e=>{e.preventDefault();e.stopPropagation();void remove(u.login)}}><X size={13}/></button>}</Link>})}{!items.length&&<div className="empty-state">{t.noData}</div>}</div></div>}

function Organizations({t,token}:{t:Copy;token:string}){const [items,setItems]=useState<GitHubOrg[]>([]);useEffect(()=>{void github<GitHubOrg[]>('/user/orgs?per_page=100',{},token).then(setItems).catch(()=>setItems([]))},[token]);return <div className="settings-section"><div className="section-bar"><div><h3>{t.organization}</h3></div></div><div className="data-list">{items.map(o=><a key={o.id} className="data-row" href={o.html_url} target="_blank" rel="noreferrer"><img src={o.avatar_url} className="row-avatar" alt=""/><div><strong>{o.login}</strong><small>{o.description||t.noDescription}</small></div><ArrowUpRight size={13}/></a>)}{!items.length&&<div className="empty-state">{t.noOrgs}</div>}</div></div>}
function Emails({t,token}:{t:Copy;token:string}){const [items,setItems]=useState<GitHubEmail[]>([]);const [newEmail,setNewEmail]=useState('');const [status,setStatus]=useState('');const refresh=useCallback(async()=>{try{const v=await github<GitHubEmail[]>('/user/emails?per_page=100',{},token);setItems(v);setStatus('')}catch(e){setStatus(e instanceof Error?e.message:t.noEmails)}},[token,t.noEmails]);useEffect(()=>{void refresh()},[refresh]);const add=async(e:FormEvent)=>{e.preventDefault();try{await github('/user/emails',{method:'POST',body:JSON.stringify({emails:[newEmail]})},token);setNewEmail('');await refresh()}catch(err){setStatus(err instanceof Error?err.message:'Email add failed')}};const remove=async(email:string)=>{try{await github('/user/emails',{method:'DELETE',body:JSON.stringify({emails:[email]})},token);await refresh()}catch(err){setStatus(err instanceof Error?err.message:'Email delete failed')}};const setVisibility=async(visibility:'public'|'private')=>{try{await github('/user/email/visibility',{method:'PATCH',body:JSON.stringify({visibility})},token);await refresh()}catch(err){setStatus(err instanceof Error?err.message:'Visibility update failed')}};return <div className="settings-section"><div className="section-bar"><div><h3>{t.emails}</h3><p>{items.length} {t.emails}</p></div><button className="action-button" onClick={()=>void refresh()}><RefreshCw size={13}/>{t.refresh}</button></div>{status&&<div className="settings-error">{status}</div>}<form className="composer compact" onSubmit={add}><div className="form-grid-2"><input required type="email" value={newEmail} onChange={e=>setNewEmail(e.target.value)} placeholder="email@example.com"/><select defaultValue="private" onChange={e=>void setVisibility(e.target.value as 'public'|'private')}><option value="private">Private</option><option value="public">Public</option></select></div><button className="action-button primary"><Plus size={13}/>{t.create}</button></form><div className="data-list">{items.map(e=><div className="data-row" key={e.email}><Globe size={14}/><div><strong>{e.email}</strong><small>{e.primary?'primary · ':''}{e.verified?'verified':'unverified'}{e.visibility?` · ${e.visibility}`:''}</small></div><button className="icon-button" onClick={()=>void remove(e.email)} title={t.deleteFile}><Trash2 size={13}/></button></div>)}{!items.length&&!status&&<div className="empty-state">{t.noEmails}</div>}</div></div>}

function Keys({t,token}:{t:Copy;token:string}){const [items,setItems]=useState<GitHubKey[]>([]);const [title,setTitle]=useState('');const [key,setKey]=useState('');const refresh=()=>void github<GitHubKey[]>('/user/keys?per_page=100',{},token).then(setItems).catch(()=>setItems([]));useEffect(refresh,[token]);const add=async(e:FormEvent)=>{e.preventDefault();await github<GitHubKey>('/user/keys',{method:'POST',body:JSON.stringify({title,key})},token);setTitle('');setKey('');refresh()};const remove=async(id:number)=>{await github(`/user/keys/${id}`,{method:'DELETE'},token);refresh()};return <div className="settings-section"><div className="section-bar"><div><h3>{t.keys}</h3></div></div><form className="composer compact" onSubmit={add}><div className="form-grid-2"><input required value={title} onChange={e=>setTitle(e.target.value)} placeholder={t.title}/><input required value={key} onChange={e=>setKey(e.target.value)} placeholder="ssh-ed25519 AAAA..."/></div><button className="action-button primary"><Plus size={13}/>{t.create}</button></form><div className="data-list">{items.map(k=><div className="data-row" key={k.id}><KeyRound size={14}/><div><strong>{k.title}</strong><small>{k.key.slice(0,48)}…</small></div><button className="icon-button" onClick={()=>remove(k.id)}><Trash2 size={13}/></button></div>)}{!items.length&&<div className="empty-state">{t.noKeys}</div>}</div></div>}
function Gists({t,token}:{t:Copy;token:string}){const [items,setItems]=useState<GitHubGist[]>([]);const [show,setShow]=useState(false);const [filename,setFilename]=useState('snippet.txt');const [content,setContent]=useState('');const [description,setDescription]=useState('');const [publicGist,setPublicGist]=useState(false);const refresh=()=>void github<GitHubGist[]>('/gists?per_page=100',{},token).then(setItems).catch(()=>setItems([]));useEffect(refresh,[token]);const create=async(e:FormEvent)=>{e.preventDefault();await github<GitHubGist>('/gists',{method:'POST',body:JSON.stringify({description,public:publicGist,files:{[filename]:{content}}})},token);setShow(false);setContent('');setFilename('snippet.txt');refresh()};return <div className="settings-section"><div className="section-bar"><div><h3>{t.gists}</h3><p>{items.length}</p></div><button className="action-button primary" onClick={()=>setShow(v=>!v)}><Plus size={13}/>{t.newGist}</button></div>{show&&<form className="composer compact" onSubmit={create}><div className="form-grid-2"><input value={filename} onChange={e=>setFilename(e.target.value)} placeholder={t.fileName}/><input value={description} onChange={e=>setDescription(e.target.value)} placeholder={t.description}/></div><textarea value={content} onChange={e=>setContent(e.target.value)} placeholder={t.body}/><label className="check-row"><input type="checkbox" checked={publicGist} onChange={e=>setPublicGist(e.target.checked)}/><span>{t.public}</span></label><button className="action-button primary">{t.createGist}</button></form>}<div className="data-list">{items.map(g=><a key={g.id} className="data-row" href={g.html_url} target="_blank" rel="noreferrer"><BookOpen size={14}/><div><strong>{g.description||g.id}</strong><small>{Object.keys(g.files).join(', ')}</small></div><ArrowUpRight size={13}/></a>)}{!items.length&&<div className="empty-state">{t.noGists}</div>}</div></div>}

export default function App(){return <Shell/>}
